def request(method, path, options, headers, raw)
        headers.merge!({
          'User-Agent' => user_agent
        })

        options.merge!({
          :client_id     => client_id,
          :client_secret => client_secret
        })

        options.merge!({
          :v => Time.now.strftime('%Y%m%d')
        })

        begin
          response = connection.request(method, paramify(path, options), headers)
        rescue OAuth2::Error => e
          Skittles::Utils.handle_foursquare_error(e.response)
        else
          Skittles::Error
        end

        unless raw
          result = Skittles::Utils.parse_json(response.body)
        end

        raw ? response : result.response
      end

def background_position=(pos)
      warn 'background_position= has no effect in nested RVG objects' if @nested
      bg_pos = pos.to_s.downcase
      raise ArgumentError, "background position must be `scaled', `tiled', or `fit' (#{pos} given)" unless %w[scaled tiled fit].include?(bg_pos)

      @background_position = bg_pos.to_sym
    end

