def wrap(width: 78, indent: 0, indent_after: false, segments: false)
    if segments
      text = Text.wrap_segments(@lines[@line], width: width, indent: indent, indent_after: indent_after)
    else
      text = Text.wrap(@lines[@line], width: width, indent: indent, indent_after: indent_after)
    end
    @lines.delete_at(@line)
    @line -= 1
    text.split("\n").each {|line| self.next(line) }
    return self
  end

def create
      @svg_file = Cmtool::SvgFile.new(svg_file_params)

      respond_to do |format|
        if @svg_file.save
          format.html { redirect_to(cmtool.svg_files_path, :notice => I18n.t('cmtool.action.create.successful', :model => Cmtool::SvgFile.model_name.human)) }
          format.xml  { render :xml => @svg_file, :status => :created, :location => @svg_file }
        else
          format.html { render :action => "new" }
          format.xml  { render :xml => @svg_file.errors, :status => :unprocessable_entity }
        end
      end
    end

