   # With an exception:
   begin
     fail 'oops'
   rescue => exception
     Honeybadger.notify(exception, context: {
       my_data: 'value'
     }) # => '-1dfb92ae-9b01-42e9-9c13-31205b70744a'
   end

   # Custom notification:
   Honeybadger.notify('Something went wrong.', {
     error_class: 'MyClass',
     context: {my_data: 'value'}
   }) # => '06220c5a-b471-41e5-baeb-de247da45a56'

