def shutdown(timeout=2)
      threads = nil

      @mutex.lock
      begin
        return false if @state == :shutdown
        @state = :shutdown

        @queue.clear
        threads, @threadpool = @threadpool, []
        @cond.broadcast
      ensure
        @mutex.unlock rescue nil
      end

      join_all(threads)

      nil
    end

