      case pBehaviour
      when Languages::KEEP_LEVEL
        @managerCondLoopAndBlock.send("add_#{pMetaData}", pElementToAdd)
      when Languages::UP_LEVEL
        @managerCondLoopAndBlock.decrease_deep_level
        @managerCondLoopAndBlock.send("add_#{pMetaData}", pElementToAdd)
      when Languages::DOWN_LEVEL
