def result
      @task = 'railsbp'
      @path = discover_path

      return unless is_rails? && temp_config(@task) && path_exists?(@path)

      tmp = Tempfile.new('railsbp')
      `rails_best_practices #{@path} -f json --output-file #{tmp.path}`
      railsbp = tmp.read
      tmp.close
      tmp.unlink

      unless railsbp.blank?
        rbj = JSON.parse(railsbp).group_by { |s| s['filename'] }
        railsbp = {}
        rbj.each do |file, errors|
          next unless file

          # This crazy gsub scrubs the absolute path from the filename
          filename = file.gsub(Rails.root.to_s, '')[1..-1]
          railsbp[filename] = errors.map { |o| hash_for_railsbp(o) }

        end
      end

      @output[:files_inspected] ||= files_inspected('rb', ' ')
      refine railsbp
    end

def to_hash
      Hash.new.tap do |hash|
        @child_options.each do |name, opt|
          # this is meant to be a "value exporter", so always use distinct values
          # on the returned hash to prevent unintentional pass-by-ref shared objects
          hash[name.to_sym] = NsOptions.distinct_value(opt.value)
        end
        @child_namespaces.each{|name, value| hash[name.to_sym] = value.to_hash}
      end
    end

