def acquire_ticket_vm(vmId)

      params = {
        'method' => :post,
        'command' => "/vApp/vm-#{vmId}/screen/action/acquireTicket"
      }

      response, headers = send_request(params)

      screen_ticket = response.css("ScreenTicket").text

      result = {}

      if screen_ticket =~ /mks:\/\/([^\/]*)\/([^\?]*)\?ticket=(.*)/
