def id_for_ref(ref)
      return ref if ref.match(/[0-9a-f]{40}/)
      unless @refs.key? ref
        options = { :timeout => false }
        sha = @grit_repo.git.native(:rev_parse, options, "#{ref}^{}")
        @refs[ref] = sha.rstrip
      end
      @refs[ref]
    end

